import importlib.util, random, itertools, json, subprocess, math
spec = importlib.util.spec_from_file_location("runmod", "/app/submit/run")
R = importlib.util.module_from_spec(spec); spec.loader.exec_module(R)

FULL=(1<<128)-1
def trunc(v,b):
    if b<=0: return 0
    if b>=128: return v
    return v & (FULL ^ ((1<<(128-b))-1))
def al(x,k): return k*((x+k-1)//k)

def indep_cost(fib,b,e):
    # fib list (val,len,hop)
    if b==0:
        keys=[0]
        def plist_for(k): return fib
    else:
        d={}
        for t in fib:
            v,l,h=t
            if l>b: d.setdefault(trunc(v,b),[]).append(t)
        keys=sorted(d)
        def plist_for(k): return d[k]
    span=e-b
    total=0
    for k in keys:
        pl=plist_for(k)
        rs=0; es=set()
        for (v,l,h) in pl:
            if l<=e: rs+=32+al(l-b,8)
            else: es.add(trunc(v,e))
        total+=al(128+rs+len(es)*(32+al(span,8)),64)
    return total

def rand_fib(rng, nmax=8):
    fib=[]; seen=set()
    n=rng.randint(0,nmax)
    for _ in range(n):
        l=rng.choice([0,1,8,16,32,48,64,96,100,127,128,rng.randint(0,128)])
        v=rng.getrandbits(128)
        v=trunc(v,l)
        key=(v,l)
        if key in seen: continue
        seen.add(key)
        fib.append((v,l,rng.randint(0,65535)))
    return fib

def brute_opt(fib,caps,ms,S):
    # enumerate cut sequences
    # costmap from indep
    cost={}
    for b in range(128):
        for e in range(b+1,min(b+ms,128)+1):
            cost[(b,e)]=indep_cost(fib,b,e)
    best=None; bestcuts=None
    # enumerate via recursion
    def rec(i,d,peak,cuts):
        nonlocal best,bestcuts
        if i==S:
            if d==128:
                if best is None or peak[0]*best[1] < best[0]*peak[1]:
                    best=peak; bestcuts=list(cuts)
            return
        emax=min(d+ms,128)
        # prune: remaining steps must be able to reach 128
        for e in range(d+1,emax+1):
            c=cost[(d,e)]
            # peak max with (c,caps[i])
            a=peak; b2=(c,caps[i])
            np = b2 if a[0]*b2[1] < b2[0]*a[1] else a
            rec(i+1,e,np,cuts+[e])
    rec(0,0,(0,1),[0])
    return best,bestcuts

def cmp_frac(a,b):
    return a[0]*b[1]-b[0]*a[1]

rng=random.Random(1234)
issues=0
for trial in range(300):
    fib=rand_fib(rng,6)
    S=rng.randint(4,6)
    ms=rng.randint(1,40)
    # ensure feasibility possible
    if S*ms<128: 
        # still test infeasible
        pass
    caps=[rng.randint(200,5000) for _ in range(S)]
    cm=R.build_costmap(fib,ms)
    # check costmap vs indep for a few pairs
    for _ in range(5):
        b=rng.randint(0,127); e=rng.randint(b+1,min(b+ms,128))
        if cm[(b,e)]!=indep_cost(fib,b,e):
            print("COSTMAP MISMATCH",trial,b,e,cm[(b,e)],indep_cost(fib,b,e)); issues+=1
    res=R.solve_cuts(cm,caps,ms,S)
    # brute only if enumeration small
    # count combos roughly
    # do brute (may be slow). limit by trial random small
    best,bc=brute_opt(fib,caps,ms,S)
    if res is None:
        if best is not None:
            print("DP infeasible but brute feasible",trial); issues+=1
    else:
        cuts,frac=res
        # compute peak from build
        st,used=R.build_stages(fib,cuts,ms)
        peak=R.max_ratio(used,caps)
        if best is None:
            print("DP feasible but brute infeasible",trial); issues+=1
        else:
            if cmp_frac(peak,best)!=0:
                print("PEAK MISMATCH",trial,peak,best,fib,caps,ms,S,cuts); issues+=1
        # check costmap consistency with used
        for i in range(S):
            if cm[(cuts[i],cuts[i+1])]!=used[i]:
                print("USED MISMATCH",trial,i); issues+=1
print("done issues",issues)
